<?php
namespace App\Services;
use App\Models\CentralFinanceStudentProfile; use App\Models\Students; use Illuminate\Support\Facades\Schema; use Throwable;
/** Read-only tenant UI bridge. Central is authoritative; tenant finance is never a fallback. */
final class CentralFinanceStudentReadBridge { public function forStudent(Students $student): array { try { if (!Schema::connection('mysql')->hasTable('central_finance_student_profiles') || !Schema::connection('mysql')->hasTable('central_finance_receivables') || !Schema::connection('mysql')->hasTable('central_finance_payments')) return ['available'=>false,'reason'=>'Central Finance is unavailable.']; $uuid=(string)$student->getAttribute('central_finance_source_uuid'); if ($uuid===''||!preg_match('/^[0-9a-f-]{36}$/i',$uuid)) return ['available'=>false,'reason'=>'Central Finance profile is not available.']; $profile=CentralFinanceStudentProfile::on('mysql')->where(['school_id'=>$student->school_id,'source_uuid'=>$uuid])->with(['receivables.payments.receipt'])->first(); if(!$profile)return ['available'=>false,'reason'=>'Central Finance profile is not available.']; $receivables=$profile->receivables; $due=(float)$receivables->sum('amount_due');$paid=(float)$receivables->sum('amount_paid');return ['available'=>true,'profile'=>$profile,'receivables'=>$receivables,'total_due'=>$due,'total_paid'=>$paid,'outstanding'=>max(0,$due-$paid)]; } catch(Throwable){ return ['available'=>false,'reason'=>'财务数据暂不可用']; } } }
